Definition ex_rem (t : list Z) (r : tokres) (i : nat) (s : list Z) : bool :=
  match r with
  | TK_tok k l => tl_ieqb t (firstn l (skipn (i + k) s))
                  || existsb (tl_ieqb t) (toks_from (S (length s - (i + k + l))) true (skipn (i + k + l) s))
  | _ => false
  end.

Lemma toks_from_S : forall f nc s,
  toks_from (S f) nc s = match tok_next nc s with
                         | TK_tok k l => firstn l (skipn k s) :: toks_from f true (skipn (k + l) s)
                         | _ => [] end.
Proof. intros. reflexivity. Qed.

Lemma token_list_exists_rem : forall s t, token_list_exists s t = ex_rem t (tok_next false s) 0 s.
Proof.
  intros s t. unfold token_list_exists, token_list_of, ex_rem. rewrite toks_from_S.
  destruct (tok_next false s) as [| |k l] eqn:R; try reflexivity.
  pose proof (tok_next_tok_bound _ _ _ _ R) as [B L].
  cbn [existsb Nat.add]. f_equal. f_equal. apply toks_from_fuel; rewrite length_skipn; lia.
Qed.

Lemma ex_rem_next : forall s t i k l, (i + k + l <= length s)%nat -> (1 <= l)%nat ->
  tl_ieqb t (firstn l (skipn (i + k) s)) = false ->
  ex_rem t (TK_tok k l) i s = ex_rem t (tok_next true (skipn (i + k + l) s)) (i + k + l) s.
Proof.
  intros s t i k l B L NM. unfold ex_rem at 1. rewrite NM. cbn [orb]. rewrite toks_from_S.
  destruct (tok_next true (skipn (i + k + l) s)) as [| |k2 l2] eqn:R; cbn [ex_rem existsb]; try reflexivity.
  pose proof (tok_next_tok_bound _ _ _ _ R) as [B2 L2]. rewrite length_skipn in B2.
  rewrite !skipn_skipn'. replace (i + k + l + (k2 + l2))%nat with (i + k + l + k2 + l2)%nat by lia.
  f_equal. f_equal. apply toks_from_fuel; rewrite length_skipn; lia.
Qed.

Lemma tl_ieqb_cons : forall x y a b, tl_ieqb (x :: a) (y :: b) = (lowerc x =? lowerc y) && tl_ieqb a b.
Proof. intros. reflexivity. Qed.
Lemma tl_ieqb_nil : tl_ieqb [] [] = true. Proof. reflexivity. Qed.

Lemma lowerc_range : forall c, 0 <= c < 256 -> 0 <= lowerc c < 256.
Proof. intros c Hc. unfold lowerc. destruct ((65 <=? c) && (c <=? 90)) eqn:E; [| lia]. apply andb_prop in E. destruct E as [E1 E2]. apply Z.leb_le in E1. apply Z.leb_le in E2. lia. Qed.

Lemma zbytes_firstn : forall n bs, zbytes (firstn n bs) = firstn n (zbytes bs).
Proof. intros n bs. unfold zbytes. rewrite firstn_map. reflexivity. Qed.

Section KIT.
  Context {HCEIL : HeapCeil}.
  Variable H : asr.
  Hypothesis HH : asan_rt_hyps H.

Lemma bytes_at_sub : forall m P bs (a n : nat), bytes_at asegs m P bs -> (a + n <= length bs)%nat ->
  bytes_at asegs m (P + Z.of_nat a) (firstn n (skipn a bs)).
Proof.
  intros m P bs a n WIN Hl.
  rewrite <- (firstn_skipn a bs) in WIN. apply bytes_at_app in WIN. destruct WIN as [_ W2].
  rewrite firstn_length_le in W2 by lia.
  rewrite <- (firstn_skipn n (skipn a bs)) in W2. apply bytes_at_app in W2. destruct W2 as [W2 _]. exact W2.
Qed.

