Lemma ex_place_windows : forall LF A n ff fp m,
  as_RFS H LF m -> fresh_frame H LF 1 ff fp -> ex_place H LF A n -> 0 <= A -> 0 <= n ->
     (A + n <= ff \/ ff + 128 <= A)
  /\ (A + n <= Z.shiftr ff 3 + 2147450880 \/ Z.shiftr ff 3 + 2147450880 + 16 <= A)
  /\ (A + n <= fp \/ fp + 1 <= A)
  /\ (A + n <= as_FSB H \/ as_FSB H + AFS_FLAGS <= A).
Proof.
  intros LF A n ff fp m RF FF (FO & NS & AH) A0 N0.
  pose proof (fsobj_windows _ HH _ _ _ _ _ _ _ RF FO FF A0 N0 AH) as (D1 & _ & D3 & D4).
  pose proof (ff_facts _ _ _ _ _ FF) as (_ & _ & _ & _ & F1 & F2 & F3 & _ & F4 & F5 & F6 & F7 & F8 & F9 & F10 & F11 & F12 & APF & APP1 & SHFF & SF1 & SF2 & SF3 & NSB).
  fs_nums_in D1. fs_nums_in SF2.
  split; [exact D1|]. split; [| split; [exact D3| exact D4]].
  rewrite SHFF. unfold ALOWSH_LO, AHI_LO in *. lia.
Qed.
