Lemma ex_it_aobj : forall LF m lo shi ff fp TL T SP TP n k,
  ex_side LF m lo shi ff fp TL T SP TP n k -> aobj m (ff + 32) 40.
Proof.
  intros LF m lo shi ff fp TL T SP TP n k (RF & AC & SK & A1 & A2 & A3 & A4 & A5).
  pose proof (fresh_of_RFS _ HH _ _ _ _ _ RF) as FF.
  pose proof (ff_facts _ _ _ _ _ FF) as (_ & _ & _ & _ & F1 & F2 & F3 & _ & F4 & F5 & F6 & F7 & F8 & F9 & F10 & F11 & F12 & APF & APP1 & SHFF & SF1 & SF2 & SF3 & NSB).
  fs_nums_in F2. fs_nums_in APF. unfold AIMG_TOP, AFS_HDR in F1.
  apply aobj_aapp; [| lia | exact A5 |].
  - eapply aapp_sub; [exact APF| lia| lia].
  - pose proof (ah_frm_shvis _ HH _ _ (1, ff, fp) RF (or_introl eq_refl)) as SV. unfold ff_addr, ff_class in SV. cbn [fst snd] in SV. fs_nums_in SV.
    eapply shvis_sub; [exact SV| lia| lia| lia| lia| lia].
Qed.

