(* [comment removed for export] *)
Definition ex_sep (A n ff fp : Z) : Prop :=
  (A + n <= ff \/ ff + 128 <= A)
  /\ (A + n <= Z.shiftr ff 3 + 2147450880 \/ Z.shiftr ff 3 + 2147450880 + 16 <= A)
  /\ (A + n <= fp \/ fp + 1 <= A).

(* [comment removed for export] *)
Definition ex_ctx (LF : list fframe) (m m1 : mem) (sp : word) (spa : Z) (gsz : nat) (gj : list byte)
    (rav s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v : word)
    (TL T SP TP : Z) (sbs tbs : list byte) (tlrest trest : list cell) (lo shi ff fp : Z)
    (h0 h1 h2 h3 : word) (fj sh16 : list byte) (ebc itc : list cell) : Prop :=
  rw_cells asegs m1 spa [C8 (wz (TL + 8)); C8 (wz ff); C8 (wz (Z.shiftr T 3 + 2147450880)); C8 (wz T); C8 (wz ff)]
  /\ rw_cells asegs m1 (spa + 40) ebc
  /\ rw_cells asegs m1 (spa + 80) (TokItCells 0 0 (SP + Z.of_nat (length sbs)) (SP + Z.of_nat (length sbs)) (SP + Z.of_nat (length sbs)))
  /\ rw_cells asegs m1 (spa + 120) [CB gsz gj]
  /\ rw_cells asegs m1 (bv_unsigned sp + -104) [C8 s11v; C8 s10v; C8 s9v; C8 s8v; C8 s7v; C8 s6v; C8 s5v; C8 s4v; C8 s3v; C8 s2v; C8 s1v; C8 s0v; C8 rav]
  /\ rw_cells asegs m1 ff [C8 h0; C8 h1; C8 h2; C8 h3]
  /\ rw_cells asegs m1 (ff + 32) itc
  /\ rw_cells asegs m1 (ff + 72) [CB 48 fj; C8 (wz fp)]
  /\ rw_cells asegs m1 (Z.shiftr ff 3 + 2147450880) [CB 16 sh16]
  /\ rw_cells asegs m1 fp [C1 (b8 1)]
  /\ rw_cells asegs m1 TL (C8 (wz SP) :: C8 (wz (Z.of_nat (length sbs))) :: tlrest)
  /\ rw_cells asegs m1 T (C8 (wz TP) :: C8 (wz (Z.of_nat (length tbs))) :: trest)
  /\ bytes_at asegs m1 SP sbs /\ bytes_at asegs m1 TP tbs
  /\ stk asegs m1 lo spa
  /\ munch (ex_W H lo sp ff fp) m m1 /\ wmono asegs m m1 /\ mem_inv asegs m1
  /\ ex_side H LF m1 lo shi ff fp TL T SP TP (Z.of_nat (length sbs)) (Z.of_nat (length tbs)).

Definition ex_pure (sp : word) (spa : Z) (gsz : nat) (TL T SP TP : Z) (sbs tbs : list byte) (tlrest trest : list cell)
    (lo shi ff fp : Z) : Prop :=
  SP + Z.of_nat (length sbs) < 2^64 /\ TP + Z.of_nat (length tbs) < 2^64
  /\ lo + AEXISTS_STACK <= bv_unsigned sp /\ aceil <= lo
  /\ (bv_unsigned sp <= TL \/ TL + Z.of_nat (cells_size (C8 (wz SP) :: C8 (wz (Z.of_nat (length sbs))) :: tlrest)) <= lo)
  /\ (bv_unsigned sp <= T \/ T + Z.of_nat (cells_size (C8 (wz TP) :: C8 (wz (Z.of_nat (length tbs))) :: trest)) <= lo)
  /\ (bv_unsigned sp <= SP \/ SP + Z.of_nat (length sbs) <= lo)
  /\ (bv_unsigned sp <= TP \/ TP + Z.of_nat (length tbs) <= lo)
  /\ bv_unsigned sp + 64 <= shi /\ TL mod 8 = 0 /\ T mod 8 = 0
  /\ spa + 120 + Z.of_nat gsz = bv_unsigned sp + -104 /\ bv_unsigned sp - 240 <= spa /\ spa mod 8 = 0
  /\ ex_sep TL (Z.of_nat (cells_size (C8 (wz SP) :: C8 (wz (Z.of_nat (length sbs))) :: tlrest))) ff fp
  /\ ex_sep T (Z.of_nat (cells_size (C8 (wz TP) :: C8 (wz (Z.of_nat (length tbs))) :: trest))) ff fp
  /\ ex_sep SP (Z.of_nat (length sbs)) ff fp /\ ex_sep TP (Z.of_nat (length tbs)) ff fp.

