(* [comment removed for export] *)

Ltac open_ectx HH sp CTX PURE :=
  destruct CTX as (L & EB & EA & GAP & SAV & FH & IT & FT & SHU & FL & TLC & TC & WS & WT & ST & MU & WM & MI & SD);
  destruct PURE as (SP64 & TP64 & LO & CEIL & SEP1 & SEP2 & SEP3 & SEP4 & SHI & TLAL & TAL & GAPE & SPA1 & SPA8 & DTL & DT & DSP & DTP);
  destruct (ex_ff_nums _ HH _ _ _ _ _ _ _ _ _ _ _ _ SD) as (FF & APF & N1 & N2 & N3 & N4 & N5 & N6 & N7 & NSF & NSP);
  pose proof (bytes_at_bound _ _ _ _ WS) as WSB; pose proof (bytes_at_bound _ _ _ _ WT) as WTB;
  pose proof (rw_cells_bound _ _ _ _ TLC) as TLB; cbn [cells_size csize] in TLB, SEP1;
  pose proof (rw_cells_bound _ _ _ _ TC) as TCB; cbn [cells_size csize] in TCB, SEP2;
  pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
  pose proof aceil_facts as (AF1 & _);
  (let D := fresh "DTL1" in pose proof DTL as (D & _ & _); cbn [cells_size csize] in D);
  (let D := fresh "DT1" in pose proof DT as (D & _ & _); cbn [cells_size csize] in D);
  (let D := fresh "DSP1" in pose proof DSP as (D & _ & _));
  (let D := fresh "DTP1" in pose proof DTP as (D & _ & _));
  hyde_disj; hydeL TLAL; hydeL TAL; hydeL SPA8; hydeL N3;
  unfold TokItCells, AEXISTS_STACK, TOKIT_STACK, AINTRIN_STACK, ex_W, AFS_FLAGS in *.

(* [comment removed for export] *)
Ltac ex_call_ctor_stack HH CTOR A Fi SP sbs cs EBH :=
  lazymatch goal with
  | SD : ex_side ?H ?LF ?mc ?lo ?shi ?ff ?fp ?TL ?T _ ?TP ?n ?k, ST : stk _ ?mc ?lo ?spa, WS : bytes_at _ ?mc SP sbs, MI : mem_inv _ ?mc,
    CEIL : aceil <= ?lo |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
    let CS := fresh "CS" in let AO := fresh "AO" in let MU2 := fresh "MU2" in let WM2 := fresh "WM2" in
    let AC := fresh "ACc" in let SK := fresh "SKc" in let AW := fresh "AWc" in
    pose proof SD as (_ & AC & SK & _ & _ & AW & _ & _);
    assert (AO : aobj mc A 40) by (eapply (aobj_stack mc lo shi); [exact SK | lia | lia | lia]);
    clear SK;
    pose proof (munch_refl [(lo, spa + 120); (ff, ff + 128)]%Z mc) as MU2; pose proof (wmono_refl asegs mc) as WM2;
    pose proof CTOR as CS; unfold tokit_ctor_stmt, tokit_ctor_post, SZ_TOKIT, TOKIT_STACK, AINTRIN_STACK, P_A_TOKEN_LIST_ITER_CTOR in CS;
    callZc (CS A Fi (SP + Z.of_nat (length sbs)) SP lo sbs cs) (clear CS EBH ST WS AC AO AW);
    [ exact EBH | first [reflexivity | assumption] | exact WS | lia | reflexivity | lia
    | dj_lia
